			'sections'       => array(
				'masthead' => array(
					'title'       => 'Heading',
					'description' => 'The heading at the top of the News & Notices page.',
					'fields'      => array(
						'label'       => array( 'type' => 'text', 'label' => 'Small label' ),
						'title'       => array( 'type' => 'text', 'label' => 'Title' ),
						'description' => array( 'type' => 'textarea', 'label' => 'Description', 'rows' => 2 ),
					),
				),
				'empty'    => array(
					'title'       => 'When empty',
					'description' => 'Shown on the page when there are no notices at all.',
					'fields'      => array(
						'text' => array( 'type' => 'textarea', 'label' => 'Text', 'rows' => 2 ),
					),
				),
				'seo'      => array(
					'title'       => 'Search & Sharing',
