						'title'       => array( 'type' => 'text', 'label' => 'Page title' ),
						'description' => array( 'type' => 'textarea', 'label' => 'Description', 'rows' => 3, 'help' => 'About 150 characters.' ),
					),
				),
			),
			'defaults'       => json_decode(
				<<<'NAMI_JSON'
{
  "seo": {
    "title": "News and Notices",
    "description": "Everything NAMI publishes in one place — standing notices, upcoming events and the record of what the school, the college and the institute have hosted in Kathmandu, filterable by institution."
  },
  "masthead": {
    "label": "News & Notices",
    "title": "What NAMI is announcing.",
